import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    h = [int(x) for x in data[1:1+n]]
    if n <= 2:
        print(0)
        return
    left, right = 0, n - 1
    left_max, right_max = 0, 0
    water = 0
    while left < right:
        if h[left] < h[right]:
            if h[left] >= left_max:
                left_max = h[left]
            else:
                water += left_max - h[left]
            left += 1
        else:
            if h[right] >= right_max:
                right_max = h[right]
            else:
                water += right_max - h[right]
            right -= 1
    print(water)

if __name__ == '__main__':
    solve()

